-- Independently authored UK-source-backed educational questions.
-- Unpublished by default. A qualified clinician must approve for commercial use.
BEGIN TRANSACTION;
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-fop-001','FOP','Dermatology','Intermediate','A child with established atopic eczema develops many similar painful vesicles and punched-out erosions over a short period. Her parent reports a recent oral herpes lesion. What is the priority action?','["Use emollients alone for 48 hours", "Start systemic aciclovir promptly and arrange same-day specialist assessment", "Prescribe an oral antihistamine as sole treatment", "Apply a potent topical steroid without reassessment", "Recommend an elimination diet"]',1,'The clustered, monomorphic vesicles and painful erosions in a child with eczema suggest eczema herpeticum, a potentially serious HSV infection. NICE CG57 recommends immediate systemic aciclovir and same-day dermatology advice. The route depends on illness severity; eye involvement requires same-day ophthalmology as well.','NICE CG57 — Atopic eczema in under 12s','https://www.nice.org.uk/guidance/cg57/chapter/recommendations',1,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-fop-001',9,'UK guideline / institutional reference independently checked','Do not delay treatment of suspected eczema herpeticum while awaiting viral confirmation.','[{"option": "A", "why_not": "Emollients do not treat disseminated HSV."}, {"option": "C", "why_not": "Antihistamines do not treat the viral infection."}, {"option": "D", "why_not": "Topical steroids alone do not address eczema herpeticum."}, {"option": "E", "why_not": "Dietary restriction has no role in acute suspected HSV infection."}]','[]','clinician_signoff_pending','independently_authored','2026-11-23');
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-fop-002','FOP','Dermatology','Foundation','During follow-up, parents of a child with eczema are uncertain how often to use moisturising therapy. Which foundational advice aligns with UK guidance?','["Stop emollients when the rash clears", "Use fragrance-free emollients regularly, including on skin that looks clear", "Use antibiotics whenever itching increases", "Avoid bathing completely", "Replace emollients with oral antihistamines"]',1,'Regular emollient use is a cornerstone of atopic eczema care. NICE recommends a choice of unperfumed emollients used daily for moisturising, washing and bathing, including when eczema is clear, with instruction on quantities and technique. Anti-inflammatory treatment is added according to severity.','NICE CG57 — Atopic eczema','https://www.nice.org.uk/guidance/cg57/chapter/recommendations',1,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-fop-002',9,'UK guideline / institutional reference independently checked','Maintenance barrier care continues between flares.','[{"option": "A", "why_not": "Barrier care should continue after improvement."}, {"option": "C", "why_not": "Increased itch alone does not justify antibiotics."}, {"option": "D", "why_not": "Routine complete avoidance of bathing is not advised."}, {"option": "E", "why_not": "Antihistamines are not substitutes for adequate skin-barrier treatment."}]','[]','clinician_signoff_pending','independently_authored','2026-11-23');
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-fop-003','FOP','Dermatology','Intermediate','A child has eczema with spreading crusting and new fever, lethargy and poor oral intake. What is the safest next step?','["Reassure without examination", "Use a topical antibiotic only regardless of severity", "Urgently assess for systemic illness and treat infection according to severity", "Prescribe antifungal cream as first-line", "Advise the family to wait for a routine review next week"]',2,'Systemic features in possible bacterial eczema infection warrant prompt clinical assessment for serious illness, including sepsis. NICE NG190 differentiates localised infection in a well patient from disease in a systemically unwell patient. Antibiotic route and admission depend on the actual severity and examination.','NICE NG190 — Secondary bacterial infection of eczema','https://www.nice.org.uk/guidance/ng190/chapter/Recommendations',1,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-fop-003',9,'UK guideline / institutional reference independently checked','Crusting alone does not automatically mean antibiotics; fever and systemic illness change the risk assessment.','[{"option": "A", "why_not": "Lethargy and poor feeding require assessment."}, {"option": "B", "why_not": "Topical treatment alone is not an adequate blanket response to systemic illness."}, {"option": "D", "why_not": "Fungal infection is not the leading concern here."}, {"option": "E", "why_not": "A delayed review is unsafe with systemic features."}]','[]','clinician_signoff_pending','independently_authored','2026-11-23');
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-fop-004','FOP','Respiratory','Intermediate','A thriving young infant has inspiratory noise that is more noticeable while feeding or crying but diminishes during quiet sleep. There is no sudden onset. Which condition is most consistent?','["Foreign-body aspiration", "Laryngomalacia", "Asthma", "Viral bronchiolitis", "Epiglottitis"]',1,'Laryngomalacia is a common cause of early infancy inspiratory stridor. Dynamic collapse of supraglottic structures leads to symptoms that can worsen with crying and feeding. Persistent stridor warrants clinical assessment and feeding/weight evaluation; severe symptoms may need airway review.','Sheffield Children’s NHS — Laryngomalacia','https://library.sheffieldchildrens.nhs.uk/laryngomalacia-or-floppy-larynx/',1,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-fop-004',10,'UK guideline / institutional reference independently checked','Noise starting early in infancy and varying with feeding supports a dynamic upper-airway cause.','[{"option": "A", "why_not": "Foreign-body aspiration typically has a sudden event."}, {"option": "C", "why_not": "Asthma usually produces expiratory wheeze, not isolated inspiratory stridor."}, {"option": "D", "why_not": "Bronchiolitis usually features an acute respiratory illness."}, {"option": "E", "why_not": "Epiglottitis is an acute potentially life-threatening presentation."}]','[]','clinician_signoff_pending','independently_authored','2026-11-23');
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-fop-005','FOP','Respiratory','Foundation','A preschool child develops hoarse speech, a seal-like cough and noisy inspiration after a cold. Which diagnosis is most likely?','["Acute bacterial pneumonia", "Viral croup", "Bronchiectasis", "Allergic rhinitis", "Chronic asthma"]',1,'Viral croup causes laryngeal and subglottic inflammation, producing a barking cough, hoarse voice and inspiratory stridor, often after a viral prodrome. Assess work of breathing and stridor at rest to identify illness severity.','NHS — Croup','https://www.nhs.uk/conditions/croup/',1,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-fop-005',10,'UK guideline / institutional reference independently checked','Barking cough plus inspiratory stridor localises the problem to the upper airway.','[{"option": "A", "why_not": "Pneumonia does not characteristically give barking cough."}, {"option": "C", "why_not": "Bronchiectasis is a chronic lower-airway disorder."}, {"option": "D", "why_not": "Rhinitis does not explain barking cough with stridor."}, {"option": "E", "why_not": "Asthma causes wheeze rather than characteristic inspiratory stridor."}]','[]','clinician_signoff_pending','independently_authored','2026-11-23');
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-fop-006','FOP','Respiratory','Intermediate','An infant develops progressively louder stridor over several weeks. Several bright red superficial vascular birthmarks are noted on the skin. Which airway lesion merits particular consideration?','["Subglottic haemangioma", "Adenoidal hypertrophy", "Acute epiglottitis", "Bilateral otitis media", "Viral pharyngitis"]',0,'Progressive stridor in early infancy associated with cutaneous infantile haemangiomas raises concern for an airway haemangioma. The RCPCH published specimen reasoning selects subglottic haemangioma for its corresponding scenario, whereas an older abbreviated key differed. This is a clinical warning, not proof that every infant with skin lesions has airway involvement.','RCPCH — FOP specimen answer key and reasoning (2026)','https://www.rcpch.ac.uk/sites/default/files/2026-02/fop_specimen_paper_-_answer_key_and_reasoning_final.pdf',0,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-fop-006',10,'UK guideline / institutional reference independently checked','Consider subglottic haemangioma in a progressively noisy infant; evaluate urgently if distressed.','[{"option": "B", "why_not": "Adenoidal enlargement is uncommon as the cause of progressive stridor in a young infant."}, {"option": "C", "why_not": "Epiglottitis is usually an acute severe illness."}, {"option": "D", "why_not": "Ear infection does not cause progressive airway stridor."}, {"option": "E", "why_not": "Viral pharyngitis is unlikely to cause a progressive weeks-long course."}]','[]','clinician_signoff_pending','independently_authored','2026-11-23');
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-fop-007','FOP','Haematology','Intermediate','A previously well child presents with new petechiae and bruises after a recent viral illness. They are afebrile, active and have no bone pain or weight loss. Which condition is a key differential?','["Immune thrombocytopenia", "Acute leukaemia with systemic symptoms", "Haemophilia A", "Hereditary spherocytosis", "Henoch–Schönlein purpura"]',0,'Immune thrombocytopenia often presents in an otherwise well child with sudden petechiae or bruising after a viral infection. The diagnosis requires evaluation including blood count and film, with alternative causes of thrombocytopenia excluded; never infer the platelet count from appearance alone.','Frimley Health NHS — Immune thrombocytopenia','https://www.fhft.nhs.uk/patients-and-visitors/patient-information-library/immune-thrombocytopenia-itp',0,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-fop-007',12,'UK guideline / institutional reference independently checked','Well child + sudden petechiae after virus suggests ITP, but confirm with FBC and review the film.','[{"option": "B", "why_not": "Leukaemia is important to exclude, but constitutional or bone features increase suspicion."}, {"option": "C", "why_not": "Haemophilia more commonly produces deep-tissue or joint bleeding."}, {"option": "D", "why_not": "Spherocytosis presents chiefly with haemolysis."}, {"option": "E", "why_not": "IgA vasculitis typically has palpable purpura and a different symptom pattern."}]','[]','clinician_signoff_pending','independently_authored','2026-11-23');
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-fop-008','FOP','Haematology','Intermediate','A child with a known haemoglobinopathy develops intense limb pain following exposure to cold, with anaemia and intermittent jaundice. Which event best explains the pain?','["Thrombocytopenic bleeding", "Vaso-occlusive sickle cell pain episode", "Immune-mediated haemolytic anaemia alone", "Acute appendicitis", "Juvenile idiopathic arthritis"]',1,'In sickle cell disease, sickled erythrocytes obstruct microvascular flow, causing painful vaso-occlusive episodes. Cold exposure may be a trigger. Jaundice can reflect ongoing haemolysis. An unwell child still requires assessment for infection and acute chest syndrome rather than assuming every pain episode is uncomplicated.','NHS — Sickle cell disease','https://www.nhs.uk/conditions/sickle-cell-disease/',0,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-fop-008',12,'UK guideline / institutional reference independently checked','Cold exposure + bone pain + haemolytic features is a high-yield sickle cell pattern.','[{"option": "A", "why_not": "A platelet disorder is not the typical mechanism for limb pain."}, {"option": "C", "why_not": "Haemolysis alone does not explain vaso-occlusive bone pain."}, {"option": "D", "why_not": "Appendicitis does not explain this haemoglobinopathy pattern."}, {"option": "E", "why_not": "Inflammatory arthritis follows a different clinical course."}]','[]','clinician_signoff_pending','independently_authored','2026-11-23');
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-fop-009','FOP','Neonatology','Intermediate','A baby fails newborn hearing screening. A congenital viral infection is confirmed and long-term audiological follow-up is arranged because hearing loss may develop or progress later. Which infection is particularly relevant?','["Congenital cytomegalovirus", "Hepatitis A", "Rotavirus", "Parvovirus B19 acquired after birth", "Rhinovirus"]',0,'Congenital cytomegalovirus is an important non-genetic cause of childhood sensorineural hearing loss. Some infants are asymptomatic at birth, and hearing loss may be delayed or progressive. NHS resources describe the need for appropriate hearing assessment and follow-up after confirmed congenital CMV.','NHS — Cytomegalovirus (CMV)','https://www.nhs.uk/conditions/cytomegalovirus-cmv/',0,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-fop-009',11,'UK guideline / institutional reference independently checked','Do not rely on a single normal hearing screen to exclude later hearing loss in congenital CMV.','[{"option": "B", "why_not": "Hepatitis A is not a typical cause of congenital progressive hearing loss."}, {"option": "C", "why_not": "Rotavirus commonly causes gastroenteritis."}, {"option": "D", "why_not": "Postnatal parvovirus is not the classic congenital hearing-loss infection."}, {"option": "E", "why_not": "Rhinovirus does not cause this congenital syndrome."}]','[{"title": "UCLH NHS — Congenital CMV", "url": "https://www.uclh.nhs.uk/patients-and-visitors/patient-information-pages/what-expect-after-congenital-cytomegalovirus-diagnosis"}]','clinician_signoff_pending','independently_authored','2026-11-23');
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-fop-010','FOP','Public Health','Foundation','Parents of a newborn ask about a simple sleep-position intervention that reduces the risk of sudden infant death syndrome. What should be recommended for every sleep?','["Prone sleeping to avoid reflux", "Side positioning with cushions", "Supine sleeping on a firm, flat, separate sleep surface", "Sleeping on a sofa with an adult", "Placing soft toys around the infant"]',2,'UK safer-sleep advice recommends putting babies on their back for every sleep, on a firm and flat surface, with a clear cot. Sofa sleeping and soft loose bedding are unsafe. The recommendation applies to routine sleep unless a specialist provides a specific alternative plan for a rare clinical circumstance.','NHS — Sudden infant death syndrome','https://www.nhs.uk/baby/caring-for-a-newborn/sudden-infant-death-syndrome-sids/',0,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-fop-010',16,'UK guideline / institutional reference independently checked','Back to sleep, clear cot, firm flat mattress.','[{"option": "A", "why_not": "Prone placement is associated with increased SIDS risk."}, {"option": "B", "why_not": "Cushions create an unsafe sleep environment."}, {"option": "D", "why_not": "Sofas are high-risk sleep settings."}, {"option": "E", "why_not": "Loose soft items are unsafe in the cot."}]','[]','clinician_signoff_pending','independently_authored','2026-11-23');
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-fop-011','FOP','Immunisation','Intermediate','A child has a documented immediate allergy to hen egg but no known reaction to vaccine components. The family asks whether an indicated measles-containing vaccination must be postponed solely because of egg allergy. What is the current UK advice?','["Egg allergy alone is not a reason to defer routine measles-containing vaccination", "Defer all measles-containing vaccines until adolescence", "Give only mumps vaccine", "Administer vaccine only after a strict egg-free diet", "Require a negative egg skin test before every dose"]',0,'Current UK immunisation guidance states that MMR and MMRV vaccines can be given to children with egg allergy, including severe allergy, under routine arrangements. Follow the age-appropriate current UK schedule and investigate any previous true vaccine-component anaphylaxis separately.','NHS — Vaccine safety','https://www.nhs.uk/vaccinations/why-vaccination-is-important-and-the-safest-way-to-protect-yourself/',0,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-fop-011',16,'UK guideline / institutional reference independently checked','Egg allergy is not a contraindication to routine MMR/MMRV vaccines; check actual vaccine-component allergy.','[{"option": "B", "why_not": "Deferral based on egg allergy alone is not supported."}, {"option": "C", "why_not": "Single-antigen substitution is not indicated for this reason."}, {"option": "D", "why_not": "Dietary changes do not alter vaccine safety."}, {"option": "E", "why_not": "Routine egg skin testing is unnecessary."}]','[{"title": "UKHSA — MMRV vaccination guide", "url": "https://www.gov.uk/government/publications/mmrv-vaccination/mmrv-vaccination-a-guide-for-parents-and-carers"}]','clinician_signoff_pending','independently_authored','2026-11-23');
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-fop-012','FOP','Neonatology','Intermediate','A term newborn develops a substantial cephalhaematoma after an assisted delivery but is feeding normally. Which complication should be actively watched for over the following days?','["Renal failure", "Hyperbilirubinaemia", "Congenital hypothyroidism", "Persistent pulmonary hypertension", "Neonatal diabetes"]',1,'Breakdown of pooled blood within a cephalhaematoma can increase unconjugated bilirubin load. Jaundice should be assessed using measured bilirubin and age-in-hours thresholds according to NICE neonatal jaundice guidance, with further monitoring determined by the clinical course.','NICE CG98 — Jaundice in newborn babies','https://www.nice.org.uk/guidance/cg98/chapter/recommendations',0,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-fop-012',17,'UK guideline / institutional reference independently checked','After cephalhaematoma, pay attention to bilirubin; management depends on actual measured levels.','[{"option": "A", "why_not": "Kidney injury is not the usual direct consequence."}, {"option": "C", "why_not": "The haematoma does not cause thyroid hormone deficiency."}, {"option": "D", "why_not": "Pulmonary hypertension is not a direct complication of scalp haematoma."}, {"option": "E", "why_not": "Neonatal diabetes is not explained by haemoglobin breakdown."}]','[]','clinician_signoff_pending','independently_authored','2026-11-23');
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-fop-013','FOP','Infectious Diseases','Intermediate','A young unvaccinated child develops fever, cough, conjunctivitis and coryza before a widespread maculopapular rash appears. Which infection is the priority public-health consideration?','["Measles", "Scarlet fever", "Hand-foot-and-mouth disease", "Chickenpox", "Roseola infantum"]',0,'A prodrome with fever, the three Cs (cough, coryza and conjunctivitis), followed by a spreading rash suggests measles. Urgent infection-control precautions and notification pathways matter because measles is highly contagious. Confirm according to local testing and public-health protocol.','NHS England — Measles guidance for healthcare services','https://www.england.nhs.uk/long-read/measles-guidance-for-healthcare-services/',0,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-fop-013',81,'UK guideline / institutional reference independently checked','Measles is a clinical and public-health urgency; consider isolation and notification.','[{"option": "B", "why_not": "Scarlet fever often includes pharyngitis and a sandpaper rash."}, {"option": "C", "why_not": "HFMD typically affects hands, feet and oral mucosa."}, {"option": "D", "why_not": "Varicella has characteristic evolving vesicles."}, {"option": "E", "why_not": "Roseola commonly features rash as fever resolves."}]','[]','clinician_signoff_pending','independently_authored','2026-11-23');
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-tas-001','TAS','Genetics','Foundation','During RNA processing, which region of a typical eukaryotic protein-coding gene is transcribed into precursor RNA but removed during splicing?','["Promoter only", "Intron", "Mature coding exon", "Telomere", "Centromere"]',1,'Introns are intervening sequences transcribed into pre-mRNA and normally removed during RNA splicing. Exons remain in the processed transcript. Abnormal splice sites can change exon inclusion and disrupt protein production.','NHS Genomics Education — Introns','https://www.genomicseducation.hee.nhs.uk/glossary/introns/',1,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-tas-001',4,'UK guideline / institutional reference independently checked','Intron = spliced out; exon = retained in mature RNA.','[{"option": "A", "why_not": "Promoters regulate transcription but are not the spliced intronic sequence."}, {"option": "C", "why_not": "Coding exons normally remain in mature mRNA."}, {"option": "D", "why_not": "Telomeres cap chromosomes."}, {"option": "E", "why_not": "Centromeres contribute to chromosome segregation."}]','[]','clinician_signoff_pending','independently_authored','2026-11-23');
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-tas-002','TAS','Genetics','Foundation','A researcher describes the portions of a gene that remain joined in mature messenger RNA after pre-mRNA splicing. What are these portions called?','["Enhancers", "Introns", "Exons", "Centrioles", "Histones"]',2,'Exons are the sections retained in mature RNA after introns are removed. Some exons contribute untranslated regions, so describing all exons as exclusively protein coding is an oversimplification.','NHS Genomics Education — Exons','https://www.genomicseducation.hee.nhs.uk/glossary/exons/',1,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-tas-002',4,'UK guideline / institutional reference independently checked','Exons are retained in the final processed RNA, including untranslated segments.','[{"option": "A", "why_not": "Enhancers are regulatory DNA sequences."}, {"option": "B", "why_not": "Introns are usually removed by splicing."}, {"option": "D", "why_not": "Centrioles are cellular structures."}, {"option": "E", "why_not": "Histones are chromatin-associated proteins."}]','[]','clinician_signoff_pending','independently_authored','2026-11-23');
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-tas-003','TAS','Genetics','Foundation','A human cell contains one copy of each autosome and a single sex chromosome rather than the usual diploid complement. Which term best describes its chromosome state?','["Triploid", "Tetraploid", "Aneuploid", "Haploid", "Mosaic"]',3,'Human gametes are normally haploid, containing one set of chromosomes (n=23). This differs from diploid somatic cells (2n=46). Aneuploidy describes a gain or loss of individual chromosomes rather than the normal complete haploid set.','NHS Genomics Education — Haploid','https://www.genomicseducation.hee.nhs.uk/glossary/haploid/',1,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-tas-003',4,'UK guideline / institutional reference independently checked','Human haploid = 23 chromosomes; diploid = 46.','[{"option": "A", "why_not": "Triploidy contains three sets of chromosomes."}, {"option": "B", "why_not": "Tetraploidy contains four sets."}, {"option": "C", "why_not": "Aneuploidy is a chromosome-number imbalance, not normal n."}, {"option": "E", "why_not": "Mosaicism means two or more genetically different cell populations."}]','[]','clinician_signoff_pending','independently_authored','2026-11-23');
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-tas-004','TAS','Haematology','Intermediate','A patient with alpha-thalassaemia is diagnosed with haemoglobin H disease. How many of the four alpha-globin genes are typically non-functional or deleted?','["One", "Two", "Three", "Four", "None"]',2,'Haemoglobin H (HbH) disease typically reflects loss or dysfunction of three alpha-globin genes. Two-gene disease often represents alpha-thalassaemia trait; four-gene loss is associated with haemoglobin Bart’s hydrops fetalis / alpha-thalassaemia major.','UCLH NHS — Alpha thalassaemia','https://www.uclh.nhs.uk/patients-and-visitors/patient-information-pages/alpha-thalassaemia',1,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-tas-004',4,'UK guideline / institutional reference independently checked','HbH = three affected alpha genes; alpha-thalassaemia major = four.','[{"option": "A", "why_not": "One gene gives a silent-carrier state in typical classification."}, {"option": "B", "why_not": "Two genes cause alpha-thalassaemia trait."}, {"option": "D", "why_not": "Four affected genes cause alpha-thalassaemia major."}, {"option": "E", "why_not": "Unaffected genes do not account for HbH disease."}]','[]','clinician_signoff_pending','independently_authored','2026-11-23');
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-fop-014','FOP','Haematology','Intermediate','A child has several weeks of limb pain, reduced energy, fever and newly noticed bruising. Anaemia and petechiae are found. Which diagnosis must be urgently investigated?','["Allergic urticaria", "Iron deficiency without other pathology", "Acute lymphoblastic leukaemia", "Uncomplicated viral rhinitis", "Atopic dermatitis"]',2,'Bone pain, constitutional symptoms, anaemia and bleeding signs raise concern for acute leukaemia due to marrow infiltration and cytopenias. Urgent blood count, blood film and paediatric review are appropriate. Some children with ALL have atypical initial presentations, so do not dismiss persistent bone pain with bruising.','RCPCH — FOP specimen reasoning (2026)','https://www.rcpch.ac.uk/sites/default/files/2026-02/fop_specimen_paper_-_answer_key_and_reasoning_final.pdf',0,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-fop-014',12,'UK guideline / institutional reference independently checked','Bone pain + anaemia + bruising/petechiae warrants urgent haematology assessment.','[{"option": "A", "why_not": "Hives alone do not cause cytopenia."}, {"option": "B", "why_not": "Isolated iron deficiency does not usually cause petechiae and bone pain."}, {"option": "D", "why_not": "A simple coryzal illness does not explain prolonged marrow-related symptoms."}, {"option": "E", "why_not": "Eczema does not explain systemic bruising and bone pain."}]','[]','clinician_signoff_pending','independently_authored','2026-11-23');
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('uk-tas-005','TAS','Haematology','Intermediate','In a red-cell genetics tutorial, haemoglobin C is discussed as an example of which type of molecular defect?','["Whole-chromosome trisomy", "Single beta-globin amino-acid substitution", "Deletion of three alpha-globin genes", "Red-cell membrane protein deficiency", "Mitochondrial DNA deletion"]',1,'Haemoglobin C is a structural beta-globin variant caused by an amino-acid substitution (classically glutamic acid to lysine at beta-chain position 6). It is a qualitative globin-chain abnormality, unlike HbH disease, which reflects alpha-globin gene loss.','UKHSA — Understanding haemoglobinopathies','https://www.gov.uk/government/publications/sickle-cell-and-thalassaemia-screening-handbook/understanding-haemoglobinopathies',1,0,1795392000,1795392000);
INSERT OR IGNORE INTO teaching_notes(question_id,source_pdf_page,evidence_level,exam_pearl,distractors_json,additional_refs_json,editorial_status,rights_basis,last_evidence_review) VALUES('uk-tas-005',4,'UK guideline / institutional reference independently checked','Differentiate haemoglobin variants (qualitative) from thalassaemias (often quantitative).','[{"option": "A", "why_not": "Trisomy affects chromosome number."}, {"option": "C", "why_not": "Three-alpha-gene loss produces HbH disease, not HbC."}, {"option": "D", "why_not": "A membrane protein defect causes hereditary spherocytosis."}, {"option": "E", "why_not": "Mitochondrial deletion is not the molecular lesion of HbC."}]','[{"title": "UK source bank — Haematology summary", "url": "https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi"}]','clinician_signoff_pending','independently_authored','2026-11-23');
COMMIT;
